<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>کاربر</title><style>body{font-family:Tahoma;background:#07111f;color:#e9f3fb;padding:30px}.panel{background:#0a1b2b;border:1px solid #1b354b;border-radius:16px;padding:20px;max-width:850px;margin:auto;display:grid;grid-template-columns:1fr 1fr;gap:10px}h1,p,button{grid-column:1/-1}label{display:block;margin:5px}input,select{width:100%;padding:10px;background:#081522;border:1px solid #29465e;color:white;border-radius:8px}button{padding:10px;background:#123b4d;color:#6ee7d0;border:0;border-radius:8px}</style><div class="panel"><h1>{{ isset($user) ? 'ویرایش کاربر' : 'ایجاد کاربر' }}</h1>@if ($errors->any())<div role="alert" style="grid-column:1/-1;background:#3b2528;border:1px solid #63343b;color:#ffb8a8;padding:12px;border-radius:8px">@foreach ($errors->all() as $error)<p style="margin:0 0 6px">{{ $error }}</p>@endforeach</div>@endif<form method="POST" action="{{ isset($user) ? route('users.update',$user) : route('users.store') }}" style="display:contents">@csrf @if(isset($user))@method('PUT')@endif @foreach(['code'=>'کد پرسنلی','first_name'=>'نام','last_name'=>'نام خانوادگی','national_id'=>'کد ملی','job_title'=>'عنوان شغلی','phone'=>'تلفن','mobile'=>'موبایل','email'=>'ایمیل','username'=>'نام کاربری'] as $field=>$label)<label>{{ $label }}<input name="{{ $field }}" value="{{ old($field,$user?->personnel?->$field ?? '') }}" required="{{ in_array($field,['code','first_name','last_name','email','username']) ? 'required' : '' }}"></label>@endforeach @if(!isset($user))<label>رمز عبور<input type="password" name="password" required></label><label>تکرار رمز عبور<input type="password" name="password_confirmation" required></label>@else<label>رمز جدید<input type="password" name="password"></label><label>تکرار رمز جدید<input type="password" name="password_confirmation"></label>@endif<label>نقش<select name="role_id"><option value="">بدون نقش</option>@foreach($roles as $role)<option value="{{ $role->id }}" @selected(isset($user) && $user->roles->contains($role->id))>{{ $role->name }}</option>@endforeach</select></label><button>ذخیره</button></form></div></html>